using System.Reflection;
using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ───────────────────────────────────────────────
    // CalculateTotal – happy-path via [DataRow]
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 2, 0.0, 20.00, DisplayName = "Two items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00, DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62, DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00, 5, 0.15, 0.00, DisplayName = "Zero price yields zero")]
    [DataRow(99.99, 0, 0.20, 0.00, DisplayName = "Zero quantity yields zero")]
    [DataRow(100.00, 1, 1.0, 200.00, DisplayName = "100% tax doubles the price")]
    public void CalculateTotal_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    // ───────────────────────────────────────────────
    // CalculateTotal – invalid arguments via [DataRow]
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, DisplayName = "Negative unit price")]
    [DataRow(10.00, -1, 0.10, DisplayName = "Negative quantity")]
    [DataRow(10.00, 1, -0.01, DisplayName = "Tax rate below zero")]
    [DataRow(10.00, 1, 1.01, DisplayName = "Tax rate above 1")]
    public void CalculateTotal_InvalidInput_Throws(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    // ───────────────────────────────────────────────
    // ApplyDiscount – happy-path via [DynamicData]
    // ───────────────────────────────────────────────

    public static IEnumerable<object[]> DiscountCases =>
    [
        [200.00m, 0m,    200.00m],  // no discount
        [200.00m, 10m,   180.00m],  // 10% off
        [200.00m, 50m,   100.00m],  // half off
        [200.00m, 100m,  0.00m],    // free
        [59.99m,  25m,   44.9925m], // fractional result
        [0.00m,   50m,   0.00m],    // zero price stays zero
    ];

    [TestMethod]
    [DynamicData(nameof(DiscountCases))]
    public void ApplyDiscount_ReturnsExpected(
        decimal price, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    // ───────────────────────────────────────────────
    // ApplyDiscount – invalid arguments via [DynamicData] with method source
    // ───────────────────────────────────────────────

    public static IEnumerable<object[]> InvalidDiscountCases()
    {
        yield return [-1m];    // below 0
        yield return [101m];   // above 100
        yield return [200m];   // far above 100
    }

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountCases), DynamicDataSourceType.Method)]
    public void ApplyDiscount_InvalidDiscount_Throws(decimal discountPercent)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, discountPercent));
    }

    // ───────────────────────────────────────────────
    // FormatPrice – quick [DataRow] coverage
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(19.99, "$", "$19.99", DisplayName = "Dollar format")]
    [DataRow(19.99, "€", "€19.99", DisplayName = "Euro format")]
    [DataRow(1000.5, "$", "$1000.50", DisplayName = "Pads to two decimals")]
    public void FormatPrice_ReturnsExpected(
        double price, string symbol, string expected)
    {
        var result = _calculator.FormatPrice((decimal)price, symbol);

        Assert.AreEqual(expected, result);
    }
}

